{#
  Row-count audit. Every conformed and datamart model writes one row per
  build via post-hook, so "when did this last load and how big was it" is a
  query, not a log search. Mirrors the enterprise metadata_audit post-hook.
#}
{% macro create_audit_table() -%}
  {% if execute %}
    create schema if not exists audit;
    create table if not exists audit.tbl_metadata_audit (
        model_name      varchar,
        row_count       bigint,
        invocation_id   varchar,
        loaded_at       timestamp
    );
  {% endif %}
{%- endmacro %}

{% macro metadata_audit() -%}
  insert into audit.tbl_metadata_audit
  select '{{ this.identifier }}', count(*), '{{ invocation_id }}', current_timestamp
  from {{ this }}
{%- endmacro %}

{#
  Surrogate keys. The enterprise convention is md5_number_upper64 on the
  natural key, first column of every dimension, suffixed _key. DuckDB has the
  same function family, so the macro is one line; on Snowflake swap the
  function name and nothing upstream changes.
#}
{% macro surrogate_key(columns) -%}
  md5_number_upper(concat_ws('|', {% for c in columns %}coalesce(cast({{ c }} as varchar), ''){% if not loop.last %}, {% endif %}{% endfor %}))
{%- endmacro %}

"""Scenario hooks for export_json.py. Replace these per scenario.

summary(con, ctx)  -> dict merged into summary.json (headline numbers)
history(con, ctx)  -> dict: one cell per pipeline step key in scenario.json,
                      plus anything else the console's log row wants.
ctx has: action, loaded, queue, next_file, passed, failed, cfg
"""


def summary(con, ctx) -> dict:
    total = con.execute("select count(*) from main.dim_customer").fetchone()[0]
    imported = con.execute(
        "select count(*) from main.dim_customer where source <> 'crm_customer'"
    ).fetchone()[0]
    blocked = con.execute(
        "select count(*) from main.dim_record_status where status <> 'new'"
    ).fetchone()[0]
    return {"customers_total": total, "customers_imported": imported,
            "duplicates_blocked": blocked}


def history(con, ctx) -> dict:
    last = ctx["loaded"][-1] if ctx["action"] != "reset" and ctx["loaded"] else None
    added = 0
    if last:
        added = con.execute(
            "select count(*) from main.dim_record_status "
            "where status = 'new' and source_file = ?", [last]).fetchone()[0]
    total = con.execute("select count(*) from main.dim_customer").fetchone()[0]
    if ctx["action"] == "reset":
        python = "reset · queue cleared"
        out = f"dim_customer → {total} records"
    elif last:
        python = f"loaded {last}.csv"
        out = f"dim_customer → added {added} records"
    else:
        python = "nothing left to load"
        out = "—"
    dbt = (f"dbt build --select {ctx['cfg']['dbt_select']} · PASS={ctx['passed']}"
           if ctx["passed"] else "—")
    return {"python": python, "dbt": dbt, "out": out, "loaded_file": last,
            "added": added}

-- Master data wins: no imported row may share a customer_id with the CRM.
with master as (
    select customer_id from {{ ref('stg_customer') }}
)

select dim_customer.customer_id
from {{ ref('dim_customer') }}
inner join master on dim_customer.customer_id = master.customer_id
where dim_customer.source <> 'crm_customer'
